function PortalInto({selector,children}:{selector:string;children:React.ReactNode}) { const [target,setTarget]=useState<Element|null>(null); useEffect(() => { setTarget(document.querySelector(selector)) ;},[selector]); return target?createPortal(children,target):null ;}
