function shareSlotPlayer(q:Quarter,key:string,line:number,index:number) { if(q.slots[key]) return q.slots[key]; if(q.formation) return ''; const legacy=[['def-left','def-right'],['mid-left','mid-center','mid-right'],['att-left','att-right']]; return q.slots[legacy[line]?.[index]]||'' ;}
async function downloadElementPng(selector:string,filename:string) { const source=document.querySelector(selector) as HTMLElement|null; if(!source) return; const clone=source.cloneNode(true) as HTMLElement; const originals=[source,...Array.from(source.querySelectorAll('*'))] as HTMLElement[],copies=[clone,...Array.from(clone.querySelectorAll('*'))] as HTMLElement[]; originals.forEach((element,index) => { const style=getComputedStyle(element); copies[index].setAttribute('style',Array.from(style).map(property => `${property}:${style.getPropertyValue(property)};`).join('')) ;}); clone.querySelectorAll('[data-capture-controls]').forEach(x => x.remove()); const width=source.scrollWidth,height=source.scrollHeight; const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}"><foreignObject width="100%" height="100%">${new XMLSerializer().serializeToString(clone)}</foreignObject></svg>`; const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'})); const image=new Image(); await new Promise<void>((resolve,reject) => { image.onload=() => resolve(); image.onerror=reject; image.src=url ;}); const canvas=document.createElement('canvas'); canvas.width=width*2; canvas.height=height*2; const context=canvas.getContext('2d'); context?.scale(2,2); context?.drawImage(image,0,0); URL.revokeObjectURL(url); const link=document.createElement('a'); link.download=filename; link.href=canvas.toDataURL('image/png'); link.click() ;}
function LineupOverview({ match,players,ownTeam,ownLogo,opponent,opponentLogo,close }: { match:Match; players:Player[]; ownTeam:string; ownLogo?:string; opponent:string; opponentLogo?:string; close:()=>void }) { const names=Object.fromEntries(players.map(p => [p.id,p.name])),absent=players.filter(p => match.absent.includes(p.id)).map(p => p.name),type=match.matchType||'competition',prefix=type==='competition'?`Periode ${match.period}, ${match.season}`:match.season,date=new Date(match.date+'T12:00:00').toLocaleDateString('nl-NL',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),home=match.location==='home'?{name:ownTeam,logo:ownLogo}:{name:opponent,logo:opponentLogo},away=match.location==='home'?{name:opponent,logo:opponentLogo}:{name:ownTeam,logo:ownLogo}; return <div className="lineup-share-backdrop"><section className="lineup-share"><header><div><span>Opstellingen · {ownTeam}</span><div className="share-teams"><span>{home.logo&&<img src={home.logo} alt=""/>}<strong>{home.name}</strong></span><b>–</b><span><strong>{away.name}</strong>{away.logo&&<img src={away.logo} alt=""/>}</span></div><p>{prefix} · {date}{match.startTime&&` - ${match.startTime}`}</p></div><div className="share-meta"><p><b>Spelbegeleider</b>{match.facilitator||'Nog niet ingevuld'}</p><p><b>Afwezig</b>{absent.length?absent.join(', '):'Niemand'}</p></div></header><div className="share-actions" data-capture-controls><button onClick={() => downloadElementPng('.lineup-share',`opstellingen-${match.date}.png`)}>Download afbeelding</button><button aria-label="Sluiten" onClick={close}>×</button></div><div className="share-grid">{match.quarters.map((q,quarterIndex) => { const formation=q.formation||[2,3,2],field=Object.values(q.slots),bench=players.filter(p => p.active&&!match.absent.includes(p.id)&&!field.includes(p.id)); const views=formation.flatMap((count,line) => Array.from({length:count},(_,index) => ({key:`line-${line}-${index}`,left:`${(index+1)/(count+1)*100}%`,top:`${67-line*(51/Math.max(1,formation.length-1))}%`,role:`${lineName(formation.length,line)} ${sideName(count,index)}`,id:shareSlotPlayer(q,`line-${line}-${index}`,line,index)}))).concat([{key:'keeper',left:'50%',top:'88%',role:'Keeper',id:q.slots.keeper||''}]); return <article key={quarterIndex}><h3><b>{quarterIndex+1}e kwart</b><span>Formatie {formation.join('-')}</span></h3><div className="share-pitch"><i className="share-half"/>{views.map(v => <div className="share-player" style={{left:v.left,top:v.top}} key={v.key}><b>{v.id?(names[v.id]?.trim().slice(0,1)||'?'):'+'}</b><span>{v.id?names[v.id]:'Vrij'}</span><small>{v.role}</small></div>)}</div><div className="share-bench"><b>Bank</b><span>{bench.length?bench.map(p => p.name).join(' · '):'Niemand'}</span></div></article> ;})}</div><footer>Opstellingen per kwart · {ownTeam}</footer></section></div> ;}
function QuarterChanges({ match,players }: { match:Match; players:Record<string,Player> }) { return <section className="quarter-changes"><header><h2>Wisseloverzicht</h2><p>Veranderingen tussen de kwartieren</p></header><div>{[1,2,3].map(i => { const before=match.quarters[i-1],after=match.quarters[i]; const prev=Object.values(before.slots),next=Object.values(after.slots); const outgoing=prev.filter(id => !next.includes(id)); const incoming=next.filter(id => !prev.includes(id)); const moved=next.filter(id => prev.includes(id)&&playerPosition(before,id)!==playerPosition(after,id)); return <article key={i}><h3>{i}e → {i+1}e kwart</h3><p><b>Uit</b>{outgoing.length?outgoing.map(id => <span key={id}>{players[id]?.name}</span>):<em>Niemand</em>}</p><p><b>In</b>{incoming.length?incoming.map(id => <span key={id}>{players[id]?.name}</span>):<em>Niemand</em>}</p><p><b>Andere positie</b>{moved.length?moved.map(id => <span key={id}>{players[id]?.name}<small>{playerPosition(before,id)} → {playerPosition(after,id)}</small></span>):<em>Niemand</em>}</p></article> ;})}</div></section> ;}
const matchScore=(m:Match) => m.goals.reduce((s,g) => { const side=g.ownGoal?(g.team==='own'?'opponent':'own'):g.team; s[side]++; return s ;},{own:0,opponent:0});
function matchWarnings(match:Match,fieldSize:number) { const warnings:string[]=[],type=match.matchType||'competition'; if(!match.date) warnings.push('De datum ontbreekt.'); if(!match.startTime) warnings.push('De aanvangstijd ontbreekt.'); if(!match.opponentId) warnings.push('De tegenstander ontbreekt.'); if(!match.season) warnings.push('Het seizoen ontbreekt.'); if(type==='competition'&&!match.league) warnings.push('De klasse ontbreekt bij deze competitiewedstrijd.'); if((type==='competition'||type==='friendly')&&!match.period) warnings.push('De periode ontbreekt.'); match.quarters.forEach((q,index) => { const players=Object.values(q.slots).filter(Boolean),unique=new Set(players); if(players.length!==fieldSize) warnings.push(`${index+1}e kwart heeft ${players.length} in plaats van ${fieldSize} spelers.`); if(unique.size!==players.length) warnings.push(`${index+1}e kwart bevat een speler op meerdere posities.`) ;}); match.goals.forEach((goal,index) => { if(goal.quarter<1||goal.quarter>4) warnings.push(`Goal ${index+1} heeft geen geldig kwart.`); if(goal.team==='own'&&!goal.ownGoal&&!goal.scorer) warnings.push(`Goal ${index+1} heeft geen doelpuntenmaker.`); if(goal.assist&&goal.assist!=='none'&&goal.assist!=='unknown'&&goal.assist===goal.scorer) warnings.push(`Bij goal ${index+1} zijn doelpuntenmaker en assistgever dezelfde speler.`) ;}); return warnings ;}
type StatsFilters={season:string;location:string;opponent:string;period:string;formation:string;limit:string};
const defaultFilters=(season:string):StatsFilters => ({season,location:'all',opponent:'all',period:'all',formation:'all',limit:'all'});
function filteredMatches(data:State,filters:StatsFilters) { let rows=data.matches.filter(m => m.status==='finished'&&(filters.season==='all'||m.season===filters.season)&&(filters.location==='all'||m.location===filters.location)&&(filters.opponent==='all'||m.opponentId===filters.opponent)&&(filters.period==='all'||String(m.period)===filters.period)&&(filters.formation==='all'||m.quarters.some(q => (q.formation||[2,3,2]).join('-')===filters.formation))).sort((a,b) => `${b.date} ${b.startTime||''}`.localeCompare(`${a.date} ${a.startTime||''}`)); if(filters.limit!=='all') rows=rows.slice(0,Number(filters.limit)); return rows ;}
const quarterAllowed=(quarter:Quarter,filters:StatsFilters) => filters.formation==='all'||(quarter.formation||[2,3,2]).join('-')===filters.formation;
function StatsFilterBar({data,value,onChange}:{data:State;value:StatsFilters;onChange:(next:StatsFilters)=>void}) { const set=(key:keyof StatsFilters,next:string) => onChange({...value,[key]:next}); const seasons=Array.from(new Set([data.settings.season,...data.matches.map(m => m.season)])).sort().reverse(),formations=Array.from(new Set(data.matches.flatMap(m => m.quarters.map(q => (q.formation||[2,3,2]).join('-'))))); return <section className="stats-filters"><header><b>Filters</b><button className="secondary" onClick={() => onChange(defaultFilters(data.settings.season))}>Herstel</button></header><div><label>Seizoen<select value={value.season} onChange={e => set('season',e.target.value)}><option value="all">Alle seizoenen</option>{seasons.map(x => <option key={x}>{x}</option>)}</select></label><label>Thuis/uit<select value={value.location} onChange={e => set('location',e.target.value)}><option value="all">Alles</option><option value="home">Thuis</option><option value="away">Uit</option></select></label><label>Tegenstander<select value={value.opponent} onChange={e => set('opponent',e.target.value)}><option value="all">Alle tegenstanders</option>{data.opponents.map(o => <option value={o.id} key={o.id}>{o.club} {o.team}</option>)}</select></label><label>Periode<select value={value.period} onChange={e => set('period',e.target.value)}><option value="all">Alle periodes</option>{[1,2,3,4].map(x => <option key={x} value={x}>{x}e</option>)}</select></label><label>Formatie<select value={value.formation} onChange={e => set('formation',e.target.value)}><option value="all">Alle formaties</option>{formations.map(x => <option key={x}>{x}</option>)}</select></label><label>Wedstrijden<select value={value.limit} onChange={e => set('limit',e.target.value)}><option value="all">Alle wedstrijden</option><option value="5">Laatste 5</option><option value="10">Laatste 10</option></select></label></div></section> ;}
function TeamOverview({ data }: { data:State }) { const [filters,setFilters]=useState<StatsFilters>(() => defaultFilters(data.settings.season)); const [minCombination,setMinCombination]=useState(1); const season=filters.season==='all'?'Alle seizoenen':filters.season; const matches=filteredMatches(data,filters); const minutes=data.settings.quarterMinutes||12.5; const opponents=Object.fromEntries(data.opponents.map(o => [o.id,o])); const scores=matches.map(m => ({m,...matchScore(m)})); const wins=scores.filter(x => x.own>x.opponent).length,draws=scores.filter(x => x.own===x.opponent).length,losses=scores.filter(x => x.own<x.opponent).length,gf=scores.reduce((s,x) => s+x.own,0),ga=scores.reduce((s,x) => s+x.opponent,0);
  const playerTotals=data.players.map(p => { let quarters=0; const positions=new Map<string,number>(); matches.forEach(m => m.quarters.forEach(q => { if(quarterAllowed(q,filters)&&Object.values(q.slots).includes(p.id)) { quarters++; const line=playerLine(q,p.id); positions.set(line,(positions.get(line)||0)+minutes) ;} })); const events=matches.flatMap(m => m.goals.filter(g => quarterAllowed(m.quarters[g.quarter-1]||emptyQ(),filters))); return {name:p.name,minutes:quarters*minutes,quarters,positions:Array.from(positions.entries()),goals:events.filter(g => g.team==='own'&&!g.ownGoal&&g.scorer===p.id).length,assists:events.filter(g => g.team==='own'&&g.assist===p.id).length} ;}).sort((a,b) => b.minutes-a.minutes); const maxMinutes=Math.max(1,...playerTotals.map(p => p.minutes)); const avg=playerTotals.length?playerTotals.reduce((s,p) => s+p.minutes,0)/playerTotals.length:0;
  const formations=new Map<string,{quarters:number,gf:number,ga:number}>(),quarterStats=[0,1,2,3].map(() => ({gf:0,ga:0})),lineStats=new Map<string,number>(),combinations=new Map<string,{names:string;line:string;size:number;quarters:number;minutes:number;gf:number;ga:number}>(); matches.forEach(m => { m.quarters.forEach((q,qi) => { const ids=Object.values(q.slots); if(!ids.length) return; const form=(q.formation||[2,3,2]).join('-'); const goals=m.goals.filter(g => g.quarter===qi+1); const fg=goals.filter(g => (g.team==='own'&&!g.ownGoal)||(g.team==='opponent'&&g.ownGoal)).length; const ag=goals.length-fg; const f=formations.get(form)||{quarters:0,gf:0,ga:0}; formations.set(form,{quarters:f.quarters+1,gf:f.gf+fg,ga:f.ga+ag}); quarterStats[qi].gf+=fg; quarterStats[qi].ga+=ag; ids.forEach(id => { const line=playerLine(q,id); lineStats.set(line,(lineStats.get(line)||0)+minutes) ;}); const lines=Array.from(new Set(ids.map(id => playerLine(q,id)))); lines.forEach(line => { const group=ids.filter(id => playerLine(q,id)===line); [2,3].forEach(size => combinationsOf(group,size).forEach(combo => { const sorted=combo.slice().sort(); const key=`${line}-${sorted.join('-')}`; const names=sorted.map(id => data.players.find(p => p.id===id)?.name).filter(Boolean).join(' & '); const old=combinations.get(key)||{names,line,size,quarters:0,minutes:0,gf:0,ga:0}; combinations.set(key,{...old,quarters:old.quarters+1,minutes:old.minutes+minutes,gf:old.gf+fg,ga:old.ga+ag}) ;})) ;}); }) ;});
  const opponentStats=new Map<string,{name:string;played:number;won:number;gf:number;ga:number}>(); scores.forEach(x => { const o=opponents[x.m.opponentId]; const old=opponentStats.get(x.m.opponentId)||{name:o?`${o.club} ${o.team}`:'Tegenstander',played:0,won:0,gf:0,ga:0}; opponentStats.set(x.m.opponentId,{...old,played:old.played+1,won:old.won+(x.own>x.opponent?1:0),gf:old.gf+x.own,ga:old.ga+x.opponent}) ;}); const homeAway=['home','away'].map(location => { const rows=scores.filter(x => x.m.location===location); return {name:location==='home'?'Thuis':'Uit',played:rows.length,wins:rows.filter(x => x.own>x.opponent).length,gf:rows.reduce((s,x) => s+x.own,0),ga:rows.reduce((s,x) => s+x.opponent,0)} ;});
  return <Manager title="Teamoverzicht" subtitle={`${season} · ${matches.length} gefilterde afgelopen wedstrijden`}><StatsFilterBar data={data} value={filters} onChange={setFilters}/><div className="team-kpis"><Stat label="Gespeeld" value={matches.length}/><Stat label="Gewonnen" value={wins}/><Stat label="Gelijk" value={draws}/><Stat label="Verloren" value={losses}/><Stat label="Goals voor" value={gf}/><Stat label="Goals tegen" value={ga}/></div><DashboardSection title="Speeltijdplanner" subtitle={`Gemiddeld ${Math.round(avg)} minuten per speler`}><PositionLegend/><div className="playing-bars">{playerTotals.map(p => <div key={p.name} className={Math.abs(p.minutes-avg)>minutes*2?'warning':''}><span><b>{p.name}</b><small>{p.quarters} kw. · {p.goals} G · {p.assists} A</small></span><i className="position-segments">{p.positions.map(([position,value]) => <b key={position} className={positionColorClass(position)} title={`${position}: ${value} min.`} style={{width:`${value/maxMinutes*100}%`}}/>)}</i><strong>{p.minutes} min.</strong></div>)}</div></DashboardSection><div className="dashboard-grid"><DashboardSection title="Goals per kwart"><div className="quarter-chart">{quarterStats.map((q,i) => <div key={i}><b>{i+1}e</b><span><i style={{height:`${Math.max(4,q.gf/Math.max(1,...quarterStats.map(x => Math.max(x.gf,x.ga)))*70)}px`}}/><em style={{height:`${Math.max(4,q.ga/Math.max(1,...quarterStats.map(x => Math.max(x.gf,x.ga)))*70)}px`}}/></span><small>{q.gf}–{q.ga}</small></div>)}</div></DashboardSection><DashboardSection title="Thuis en uit"><div className="compact-metrics">{homeAway.map(x => <div key={x.name}><b>{x.name}</b><strong>{x.wins}/{x.played} gewonnen</strong><small>{x.gf} voor · {x.ga} tegen</small></div>)}</div></DashboardSection></div><DashboardSection title="Formaties" subtitle="Indicatief: goals zijn per kwart gekoppeld"><div className="dashboard-table formation-dashboard"><div><b>Formatie</b><b>Kwarten</b><b>Voor</b><b>Tegen</b><b>Gem. voor</b><b>Gem. tegen</b></div>{Array.from(formations.entries()).sort((a,b) => b[1].quarters-a[1].quarters).map(([name,x]) => <div key={name}><strong>{name}</strong><span>{x.quarters}</span><span>{x.gf}</span><span>{x.ga}</span><span>{(x.gf/x.quarters).toFixed(2)}</span><span>{(x.ga/x.quarters).toFixed(2)}</span></div>)}</div></DashboardSection><div className="dashboard-grid"><DashboardSection title="Meest gebruikte linies"><SimpleBars rows={Array.from(lineStats.entries()).sort((a,b) => b[1]-a[1]).map(([name,value]) => ({name,value,label:`${value} min.`}))}/></DashboardSection><DashboardSection title="Meest voorkomende combinaties" subtitle="Goals zijn indicatief aan gezamenlijke kwartieren gekoppeld"><div className="combination-filter"><label>Minimaal <input type="number" min="1" value={minCombination} onChange={e => setMinCombination(Math.max(1,+e.target.value||1))}/> gezamenlijke kwartieren</label></div><div className="dashboard-table combo-dashboard detailed"><div><b>Combinatie</b><b>Linie</b><b>Spelers</b><b>Kw.</b><b>Min.</b><b>Voor</b><b>Tegen</b><b>Saldo/kw.</b></div>{Array.from(combinations.values()).filter(x => x.quarters>=minCombination).sort((a,b) => b.quarters-a.quarters||b.size-a.size).map((x,i) => <div key={`${x.line}-${x.names}-${i}`}><strong>{x.names}</strong><span className={`position-label ${positionColorClass(x.line)}`}>{x.line}</span><span>{x.size}</span><span>{x.quarters}</span><span>{x.minutes}</span><span>{x.gf}</span><span>{x.ga}</span><span className={x.gf-x.ga>0?'positive':x.gf-x.ga<0?'negative':''}>{((x.gf-x.ga)/x.quarters).toFixed(2)}</span></div>)}</div></DashboardSection></div><DashboardSection title="Resultaten per tegenstander"><div className="dashboard-table opponents-dashboard"><div><b>Tegenstander</b><b>Gespeeld</b><b>Gewonnen</b><b>Doelsaldo</b></div>{Array.from(opponentStats.values()).sort((a,b) => b.played-a.played).map(x => <div key={x.name}><strong>{x.name}</strong><span>{x.played}</span><span>{x.won}</span><span>{x.gf}–{x.ga}</span></div>)}</div></DashboardSection></Manager> ;}
function positionColorClass(position:string) { return `position-${position.toLowerCase().replaceAll(' ','-')}` ;}
function PositionLegend() { return <div className="position-legend">{['Keeper','Verdediging','Middenveld','Verdedigend middenveld','Aanvallend middenveld','Aanval'].map(position => <span key={position}><i className={positionColorClass(position)}/>{position}</span>)}</div> ;}
function DashboardSection({title,subtitle,children}:{title:string;subtitle?:string;children:React.ReactNode}) { return <section className="dashboard-card"><header><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</header>{children}</section> ;}
function SimpleBars({rows}:{rows:Array<{name:string;value:number;label:string}>}) { const max=Math.max(1,...rows.map(r => r.value)); return <div className="simple-bars">{rows.map(r => <div key={r.name}><span>{r.name}</span><i><b style={{width:`${r.value/max*100}%`}}/></i><strong>{r.label}</strong></div>)}</div> ;}
function downloadFile(name:string,type:string,text:string) { const url=URL.createObjectURL(new Blob([text],{type})); const a=document.createElement('a'); a.href=url; a.download=name; a.click(); URL.revokeObjectURL(url) ;}
function AdminView({setData}:{setData:React.Dispatch<React.SetStateAction<State>>}) { const [versions,setVersions]=useState<VersionMeta[]>([]),[current,setCurrent]=useState<{revision:number;createdAt:string}|null>(null),[status,setStatus]=useState('laden'); const receive=(result:{current:{revision:number;createdAt:string}|null;versions:VersionMeta[]}) => { setCurrent(result.current); setVersions(result.versions); setStatus('klaar') ;}; const requestVersions=() => fetch('/api/state?versions=1').then(async response => { if(!response.ok) throw 0; return await response.json() as {current:{revision:number;createdAt:string}|null;versions:VersionMeta[]} ;}); const load=() => { setStatus('laden'); requestVersions().then(receive).catch(() => setStatus('fout')) ;}; useEffect(() => { requestVersions().then(receive).catch(() => setStatus('fout')) ;},[]); const restore=async(version:VersionMeta) => { const timestamp=new Date(version.createdAt).toLocaleString('nl-NL',{dateStyle:'medium',timeStyle:'medium'}); if(!confirm(`Versie van ${timestamp} terugzetten?\n\nDe huidige gegevens blijven als herstelversie bewaard.`)) return; setStatus('herstellen'); try { const response=await fetch('/api/state',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({versionId:version.id})}); if(!response.ok) throw 0; const result=await response.json() as {state:State}; setData({...result.state,players:result.state.players.map(p => ({...p,name:p.name.trim()})),matches:result.state.matches.map(m => ({...m,matchType:m.matchType||'competition'}))}); setStatus('hersteld'); load() ;} catch { setStatus('fout') ;} }; const format=(value:string) => new Date(value).toLocaleString('nl-NL',{dateStyle:'medium',timeStyle:'medium'}); return <Manager title="Admin" subtitle="Versiebeheer en herstelpunten"><section className="version-card"><header><div><h2>Opgeslagen versies</h2><p>De laatste 5 verschillende versies worden automatisch bewaard.</p></div><button className="secondary" onClick={load}>Vernieuwen</button></header>{current&&<div className="current-version"><span>Huidige versie</span><strong>{format(current.createdAt)}</strong><small>Versie {current.revision}</small></div>}{status==='laden'&&!versions.length?<div className="empty">Versies laden…</div>:status==='fout'?<div className="version-error">Versies konden niet worden geladen.</div>:<div className="version-list"><div className="version-row head"><span>Tijdstip</span><span>Versie</span><span>Actie</span></div>{versions.map(version => <div className="version-row" key={version.id}><strong>{format(version.createdAt)}</strong><span>{version.revision}</span><button disabled={status==='herstellen'} onClick={() => restore(version)}>Terugzetten</button></div>)}{!versions.length&&<div className="empty">Er zijn nog geen oudere versies. Die verschijnen na de volgende opgeslagen wijziging.</div>}</div>}</section></Manager> ;}
function ArchiveView({data,setData}:{data:State;setData:React.Dispatch<React.SetStateAction<State>>}) { const [newSeason,setNewSeason]=useState(() => { const year=Number(data.settings.season.slice(0,4))||new Date().getFullYear(); return `${year+1}/${year+2}` ;}); const seasons=Array.from(new Set([data.settings.season,...data.matches.map(m => m.season)])).sort().reverse(); const exportCsv=() => { const header=['seizoen','datum','tijd','thuis_uit','tegenstander','status','goals_voor','goals_tegen']; const rows=data.matches.map(m => { const o=data.opponents.find(x => x.id===m.opponentId),s=matchScore(m); return [m.season,m.date,m.startTime||'',m.location==='home'?'thuis':'uit',[o?.club,o?.team].filter(Boolean).join(' '),m.status,s.own,s.opponent] ;}); const csv=[header,...rows].map(row => row.map(v => `"${String(v).replaceAll('"','""')}"`).join(',')).join('\n'); downloadFile('voetbalstatistieken-wedstrijden.csv','text/csv;charset=utf-8',csv) ;}; const restore=(file:File|undefined) => { if(!file) return; const reader=new FileReader(); reader.onload=() => { try { const state=JSON.parse(String(reader.result)) as State; if(!state.settings||!Array.isArray(state.players)||!Array.isArray(state.matches)) throw 0; if(confirm('Deze back-up herstellen? De huidige gegevens worden vervangen.')) setData(state) ;} catch { alert('Dit is geen geldige back-up van Voetbalstatistieken.') ;} }; reader.readAsText(file) ;}; return <Manager title="Archief" subtitle="Seizoenen, exports en volledige back-ups"><div className="archive-grid"><DashboardSection title="Nieuw seizoen" subtitle="Spelers en tegenstanders blijven behouden"><div className="new-season"><input value={newSeason} onChange={e => setNewSeason(e.target.value)} placeholder="2027/2028"/><button onClick={() => { if(!newSeason.trim()) return; if(confirm(`Seizoen ${newSeason} starten? Oude wedstrijden blijven in het archief.`)) setData(d => ({...d,settings:{...d.settings,season:newSeason.trim()}})) ;}}>Start leeg seizoen</button></div></DashboardSection><DashboardSection title="Export & back-up"><div className="export-actions"><button onClick={() => downloadFile('voetbalstatistieken-backup.json','application/json',JSON.stringify(data,null,2))}>Download JSON-back-up</button><button className="secondary" onClick={exportCsv}>Exporteer wedstrijden als CSV</button><label>Back-up herstellen<input type="file" accept="application/json,.json" onChange={e => restore(e.target.files?.[0])}/></label></div></DashboardSection></div><DashboardSection title="Seizoensarchief"><div className="season-list">{seasons.map(season => { const games=data.matches.filter(m => m.season===season),finished=games.filter(m => m.status==='finished'),scores=finished.map(matchScore); return <article key={season} className={season===data.settings.season?'current':''}><h3>{season}{season===data.settings.season&&<span>Huidig</span>}</h3><div><b>{games.length}<small>wedstrijden</small></b><b>{finished.filter((m,i) => scores[i].own>scores[i].opponent).length}<small>gewonnen</small></b><b>{scores.reduce((s,x) => s+x.own,0)}–{scores.reduce((s,x) => s+x.opponent,0)}<small>doelsaldo</small></b></div></article> ;})}</div></DashboardSection></Manager> ;}
function playerLine(q: Quarter,playerId: string) { const key=Object.entries(q.slots).find(([,id]) => id===playerId)?.[0]; if(!key) return ''; if(key==='keeper') return 'Keeper'; if(key.startsWith('line-')) return lineName((q.formation||[2,3,2]).length,Number(key.split('-')[1])); if(key.startsWith('def-')) return 'Verdediging'; if(key.startsWith('mid-')) return 'Middenveld'; if(key.startsWith('att-')) return 'Aanval'; return 'Onbekend' ;}
function combinationsOf<T>(items:T[],size:number):T[][] { if(size===0) return [[]]; if(items.length<size) return []; return items.flatMap((item,index) => combinationsOf(items.slice(index+1),size-1).map(rest => [item,...rest])) ;}
function playerPosition(q: Quarter,playerId: string) { const key=Object.entries(q.slots).find(([,id]) => id===playerId)?.[0]; if(!key) return ''; if(key==='keeper') return 'Keeper'; if(key.startsWith('line-')) { const [,line,index]=key.split('-').map(Number); const formation=q.formation||[2,3,2]; return `${lineName(formation.length,line)} ${sideName(formation[line]||1,index)}` ;} if(key.startsWith('def-')) return `Verdediging ${key.endsWith('left')?'links':'rechts'}`; if(key.startsWith('mid-')) return `Middenveld ${key.endsWith('left')?'links':key.endsWith('right')?'rechts':'centraal'}`; if(key.startsWith('att-')) return `Aanval ${key.endsWith('left')?'links':'rechts'}`; return 'Onbekend' ;}
function visualStatPosition(position:string) { return position==='Middenveld centraal-links'?'Middenveld centraal':position ;}
function PlayerStatistics({ player,data,tab,setTab }: { player: Player; data: State; tab: string; setTab: (tab: string) => void ;}) {
  const [filters,setFilters]=useState<StatsFilters>(() => defaultFilters(data.settings.season)); const minutes=data.settings.quarterMinutes||12.5; const matches=filteredMatches(data,filters); const opponents=Object.fromEntries(data.opponents.map(o => [o.id,o])); const players=Object.fromEntries(data.players.map(p => [p.id,p]));
  const appearances=matches.map(m => { const played=m.quarters.map((q,i) => ({ q,i,line: playerLine(q,player.id),position: playerPosition(q,player.id) })).filter(x => x.line&&quarterAllowed(x.q,filters)); if(!played.length) return null; const allowedQuarters=new Set(played.map(x => x.i+1)),events=m.goals.filter(g => allowedQuarters.has(g.quarter)),score=matchScore(m); return { match:m,played,minutes:played.length*minutes,goals:events.filter(g => g.team==='own'&&!g.ownGoal&&g.scorer===player.id).length,assists:events.filter(g => g.team==='own'&&g.assist===player.id).length,ownGoals:score.own,against:score.opponent } ;}).filter(Boolean) as Array<{ match: Match; played: Array<{q:Quarter;i:number;line:string;position:string}>; minutes:number; goals:number; assists:number; ownGoals:number; against:number }>;
  const missed=matches.filter(m => m.absent.includes(player.id)).length,availableMatches=Math.max(0,matches.length-missed),attendance=matches.length?Math.round(availableMatches/matches.length*100):0,totalMinutes=appearances.reduce((sum,item) => sum+item.minutes,0),minutesPerAvailable=availableMatches?Math.round(totalMinutes/availableMatches*10)/10:0,availableMaximum=availableMatches*4*minutes;
  const positions=new Map<string,{quarters:number;minutes:number;gf:number;ga:number;wins:number;goals:number;assists:number}>(); appearances.forEach(a => a.played.forEach(x => { const position=visualStatPosition(x.position),events=a.match.goals.filter(g => g.quarter===x.i+1),gf=events.filter(g => (g.team==='own'&&!g.ownGoal)||(g.team==='opponent'&&g.ownGoal)).length,ga=events.length-gf; const old=positions.get(position)||{ quarters:0,minutes:0,gf:0,ga:0,wins:0,goals:0,assists:0 }; positions.set(position,{quarters:old.quarters+1,minutes:old.minutes+minutes,gf:old.gf+gf,ga:old.ga+ga,wins:old.wins+(gf>ga?1:0),goals:old.goals+events.filter(g => g.team==='own'&&!g.ownGoal&&g.scorer===player.id).length,assists:old.assists+events.filter(g => g.team==='own'&&g.assist===player.id).length}) ;})); const maxPosition=Math.max(1,...Array.from(positions.values()).map(x => x.minutes));
  const combos=new Map<string,{names:string;position:string;quarters:number;minutes:number;goals:number;assists:number;gf:number;ga:number}>(); appearances.forEach(a => a.played.forEach(x => { const teammateIds=Object.values(x.q.slots).filter(id => id&&id!==player.id&&playerLine(x.q,id)===x.line).sort(); if(!teammateIds.length) return; const events=a.match.goals.filter(g => g.quarter===x.i+1),gf=events.filter(g => (g.team==='own'&&!g.ownGoal)||(g.team==='opponent'&&g.ownGoal)).length,ga=events.length-gf,key=`${x.line}:${teammateIds.join(',')}`,names=teammateIds.map(id => players[id]?.name||'Onbekend').sort().join(' · '),old=combos.get(key)||{ names,position:x.line,quarters:0,minutes:0,goals:0,assists:0,gf:0,ga:0 }; combos.set(key,{...old,quarters:old.quarters+1,minutes:old.minutes+minutes,goals:old.goals+events.filter(g => g.team==='own'&&!g.ownGoal&&g.scorer===player.id).length,assists:old.assists+events.filter(g => g.team==='own'&&g.assist===player.id).length,gf:old.gf+gf,ga:old.ga+ga}) ;}));
  const eventRows=(kind:'goal'|'assist') => matches.flatMap(m => m.goals.map(g => ({ m,g })).filter(({m,g}) => quarterAllowed(m.quarters[g.quarter-1]||emptyQ(),filters)&&(kind==='goal'? g.team==='own'&&!g.ownGoal&&g.scorer===player.id:g.team==='own'&&g.assist===player.id)).map(({m,g}) => ({ position: playerPosition(m.quarters[g.quarter-1]||emptyQ(),player.id)||'Niet opgesteld',route: routeName(g.route),opponent: [opponents[m.opponentId]?.club,opponents[m.opponentId]?.team].filter(Boolean).join(' ')||'Tegenstander',quarter: g.quarter,location: m.location==='home'? 'Thuis':'Uit',date: m.date })));
  const goals=eventRows('goal'),assists=eventRows('assist'); const tabs=[['matches','Wedstrijden'],['positions','Posities'],['combinations','Combinaties'],['goals','Goals & assists']];
  return <section className="player-stats"><StatsFilterBar data={data} value={filters} onChange={setFilters}/><div className="stats-summary attendance-summary"><Stat label="Wedstrijden" value={appearances.length}/><Stat label="Minuten" value={Math.round(totalMinutes*10)/10}/><Stat label="Goals" value={goals.length}/><Stat label="Assists" value={assists.length}/><Stat label="Gemist" value={missed}/><Stat label="Aanwezig" value={attendance}/><Stat label="Min./beschikbaar" value={minutesPerAvailable}/><Stat label="Van beschikbare tijd" value={availableMaximum?Math.round(totalMinutes/availableMaximum*100):0}/></div><div className="attendance-note">Aanwezigheid en percentages volgen de actieve statistiekfilters. Percentages worden als hele procenten weergegeven.</div><div className="stats-tabs">{tabs.map(([id,label]) => <button key={id} className={tab===id?'active':''} onClick={() => setTab(id)}>{label}</button>)}</div>
    {tab==='matches'&&<div className="stats-table matches-stats"><div className="stats-row head"><span>Wedstrijd</span><span>Uitslag</span><span>Min.</span><span>G</span><span>A</span></div>{appearances.map(a => { const o=opponents[a.match.opponentId]; const result=a.ownGoals>a.against?'W':a.ownGoals<a.against?'V':'G'; return <div className="stats-row" key={a.match.id}><span><small>{new Date(a.match.date+'T12:00:00').toLocaleDateString('nl-NL',{day:'numeric',month:'short',year:'2-digit'})}</small><b>{o?`${o.club} ${o.team}`:'Tegenstander'}</b><em>{a.match.location==='home'?'Thuis':'Uit'}</em></span><span><i className={`result ${result}`}>{result}</i>{a.ownGoals} – {a.against}</span><strong>{a.minutes}</strong><strong>{a.goals||'–'}</strong><strong>{a.assists||'–'}</strong></div>})}</div>}
    {tab==='positions'&&<PositionAnalysis positions={positions} maxMinutes={maxPosition}/>}
    {tab==='combinations'&&<div className="stats-table combo-stats"><div className="stats-row head"><span>Medespelers</span><span>Linie</span><span>Kw.</span><span>Min.</span><span>G</span><span>A</span><span>Voor</span><span>Tegen</span></div>{Array.from(combos.values()).sort((a,b) => b.minutes-a.minutes).map((c,i) => <div className="stats-row" key={`${c.names}-${c.position}-${i}`}><strong>{c.names}</strong><span className={`position-label ${positionColorClass(c.position)}`}>{c.position}</span><span>{c.quarters}</span><strong>{c.minutes}</strong><span>{c.goals}</span><span>{c.assists}</span><span>{c.gf}</span><span>{c.ga}</span></div>)}</div>}
    {tab==='goals'&&<div className="events-grid"><EventTable title="Goals" rows={goals}/><EventTable title="Assists" rows={assists}/></div>}
  </section> ;
}
function routeName(route:string) { return ({ left: 'Over links',right: 'Over rechts',middle: 'Door het midden',corner: 'Corner','free-kick': 'Vrije trap',penalty: 'Penalty' } as Record<string,string>)[route]||route||'Onbekend' ;}
type PositionValue={quarters:number;minutes:number;gf:number;ga:number;wins:number;goals:number;assists:number};
function PositionAnalysis({positions,maxMinutes}:{positions:Map<string,PositionValue>;maxMinutes:number}) { const rows=Array.from(positions.entries()).sort((a,b) => b[1].minutes-a[1].minutes); const coordinates=(name:string) => { const lower=name.toLowerCase(),left=lower.includes('uiterst links')?10:lower.includes('links')?25:lower.includes('uiterst rechts')?90:lower.includes('rechts')?75:50,top=lower.includes('keeper')?88:lower.includes('verdediging')?72:lower.includes('verdedigend')?58:lower.includes('aanvallend middenveld')?40:lower.includes('middenveld')?50:25; return {left:`${left}%`,top:`${top}%`} ;}; return <div className="position-analysis"><section className="position-heatmap"><div className="halfway"/>{rows.map(([name,value]) => <span key={name} className={positionColorClass(name.split(' centraal')[0].split(' links')[0].split(' rechts')[0])} style={{...coordinates(name),width:22+value.minutes/maxMinutes*24,height:22+value.minutes/maxMinutes*24}} title={`${name}: ${value.minutes} minuten`}><b>{value.quarters}</b></span>)}</section><section className="position-breakdown"><p>Samenhang per gebruikte positie; dit toont geen bewezen oorzaak van het resultaat.</p><div className="dashboard-table position-result-table"><div><b>Positie</b><b>Kw.</b><b>Min.</b><b>G</b><b>A</b><b>Voor</b><b>Tegen</b><b>Winstkw.</b></div>{rows.map(([name,value]) => <div key={name}><strong className={`position-label ${positionColorClass(name.split(' centraal')[0].split(' links')[0].split(' rechts')[0])}`}>{name}</strong><span>{value.quarters}</span><span>{value.minutes}</span><span>{value.goals}</span><span>{value.assists}</span><span>{value.gf}</span><span>{value.ga}</span><span>{value.wins}</span></div>)}</div></section>{!rows.length&&<div className="empty">Nog geen positiegegevens.</div>}</div> ;}
function EventTable({ title,rows }: { title:string; rows:Array<{position:string;route:string;opponent:string;quarter:number;location:string;date:string}> ;}) { return <section><h3>{title} <span>{rows.length}</span></h3><div className="stats-table event-stats"><div className="stats-row head"><span>Positie</span><span>Soort</span><span>Tegenstander</span><span>Kwart</span><span>T/U</span></div>{rows.map((r,i) => <div className="stats-row" key={`${r.date}-${i}`}><strong className={`position-label ${positionColorClass(r.position.split(' centraal')[0].split(' links')[0].split(' rechts')[0])}`}>{r.position}</strong><span>{r.route}</span><span>{r.opponent}</span><span>{r.quarter}e</span><span>{r.location}</span></div>)}{!rows.length&&<div className="empty">Nog geen {title.toLowerCase()}.</div>}</div></section> ;}
function TeamBadge({ logo,name }: { logo?: string; name: string ;}) { return <div className="team-badge">{logo? <img src={logo} alt="" />:<i>{name.slice(0,2).toUpperCase()}</i>}<strong>{name}</strong></div> ;}
function ScoreTimeline({ goals,players,opponent,leftSide,ownTeam }: { goals: Goal[]; players: Record<string,Player>; opponent: string; leftSide: 'own'|'opponent'; ownTeam: string ;}) { const groups=goals.reduce<Array<{quarter:number;goals:Array<{goal:Goal;index:number}>}>>((result,goal,index) => { const last=result.at(-1); if(last?.quarter===goal.quarter) last.goals.push({goal,index}); else result.push({quarter:goal.quarter,goals:[{goal,index}]}); return result ;},[]); return <div className="score-timeline">{groups.map((group,groupIndex) => <section className="score-quarter" key={`${group.quarter}-${groupIndex}`}><div className="score-quarter-label"><span>{group.quarter}e kwart</span></div>{group.goals.map(({goal:g,index}) => { const side=g.ownGoal? (g.team==='own'? 'opponent':'own'):g.team; const name=side==='own'? (g.ownGoal? `Eigen doelpunt ${opponent}`:players[g.scorer]?.name||ownTeam):opponent; const item=<span><b>{name}</b></span>; return <div className="score-goal" key={g.id}><em>{index+1}</em>{side===leftSide?item:<span/>}<i>⚽</i>{side!==leftSide?item:<span/>}</div> ;})}</section>)}</div> ;}
function LogoInput({ logo,label,onFile }: { logo?: string; label: string; onFile: (file: File|undefined) => void ;}) { return <label className="logo-input" title="Logo kiezen">{logo? <img src={logo} alt={label} />:<span>+ logo</span>}<input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" onChange={e => onFile(e.target.files?.[0])} /></label> ;}
function Modal({ title,close,children }: { title: string; close: () => void; children: React.ReactNode ;}) { return <div className="modal-backdrop" onMouseDown={e => { if(e.target===e.currentTarget) close() ;}}><section className="modal"><header><h2>{title}</h2><button onClick={close}>×</button></header>{children}</section></div> ;}
function SimpleDialog({ title,fields,close,saveValues }: { title: string; fields: string[]; close: () => void; saveValues: (v: string[]) => void ;}) { const [v,setV]=useState(fields.map(() => '')); return <Modal title={title} close={close}><form onSubmit={e => { e.preventDefault(); if(v[0].trim()) saveValues(v) ;}}>{fields.map((f,i) => <label key={f}>{f}<input autoFocus={i===0} required value={v[i]} onChange={e => setV(x => x.map((a,j) => j===i? e.target.value:a))} /></label>)}<footer><button type="button" className="secondary" onClick={close}>Annuleren</button><button>Opslaan</button></footer></form></Modal> ;}
function GoalDialog({ players,quarter,ownTeam,opponent,initial,close,saveGoal }: { players: Player[]; quarter: number; ownTeam: string; opponent: string; initial?:Goal; close: () => void; saveGoal: (g: Omit<Goal,'id'>) => void ;}) { const [g,setG]=useState<Omit<Goal,'id'>>(initial?{quarter:initial.quarter,team:initial.team,scorer:initial.scorer,assist:initial.assist,ownGoal:initial.ownGoal,route:initial.route,note:initial.note}:{ quarter,team:'own',scorer:'',assist:'none',ownGoal:false,route:'middle',note:'' }); const set=(k: keyof typeof g,v: unknown) => setG(x => ({ ...x,[k]: v })); return <Modal title={initial?'Doelpunt bewerken':'Doelpunt registreren'} close={close}><form onSubmit={e => { e.preventDefault(); if(g.team==='own'&&!g.ownGoal&&!g.scorer) return; saveGoal(g) ;}}><div className="form-grid"><label>Kwart<select value={g.quarter} onChange={e => set('quarter',+e.target.value)}>{[1,2,3,4].map(x => <option key={x}>{x}</option>)}</select></label><label>Scorend team<select value={g.team} onChange={e => set('team',e.target.value)}><option value="own">{ownTeam}</option><option value="opponent">{opponent}</option></select></label></div><label className="check"><input type="checkbox" checked={g.ownGoal} onChange={e => set('ownGoal',e.target.checked)} /> Eigen doelpunt</label>{g.team==='own'&&!g.ownGoal&&<label>Doelpuntenmaker<select required value={g.scorer} onChange={e => set('scorer',e.target.value)}><option value="">Kies speler</option>{players.filter(p => p.active).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label>}<label>Assist<select value={g.assist} onChange={e => set('assist',e.target.value)}><option value="none">Geen assist</option><option value="unknown">Assist onbekend</option>{g.team==='own'&&players.filter(p => p.active).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label>Totstandkoming<select value={g.route} onChange={e => set('route',e.target.value)}><option value="left">Over links</option><option value="right">Over rechts</option><option value="middle">Door het midden</option><option value="corner">Via een corner</option><option value="free-kick">Via een vrije trap</option><option value="penalty">Via een penalty</option></select></label><label>Notitie<textarea value={g.note} onChange={e => set('note',e.target.value)} /></label><footer><button type="button" className="secondary" onClick={close}>Annuleren</button><button>{initial?'Wijzigingen opslaan':'Goal opslaan'}</button></footer></form></Modal> ;}
function MatchDialog({ match,opponents,close,saveMatch,remove }: { match: Match; opponents: Opponent[]; close: () => void; saveMatch: (m: Match) => void; remove: () => void ;}) { const [m,setM]=useState({...match,matchType:match.matchType||'competition'}); const set=(k: keyof Match,v: unknown) => setM(x => ({ ...x,[k]: v })); const type=m.matchType||'competition'; return <Modal title="Wedstrijdgegevens" close={close}><form onSubmit={e => { e.preventDefault(); saveMatch(m) ;}}><div className="form-grid"><label>Wedstrijdsoort<select value={type} onChange={e => set('matchType',e.target.value)}><option value="competition">Competitiewedstrijd</option><option value="friendly">Oefenwedstrijd</option><option value="cup">Bekerwedstrijd</option></select></label><label>Datum<input type="date" value={m.date} onChange={e => set('date',e.target.value)} /></label><label>Aanvangstijd<input type="time" value={m.startTime||''} onChange={e => set('startTime',e.target.value)} /></label><label>Tegenstander<select value={m.opponentId} onChange={e => set('opponentId',e.target.value)}>{opponents.map(o => <option key={o.id} value={o.id}>{o.club} {o.team}</option>)}</select></label><label>Seizoen *<input required value={m.season} onChange={e => set('season',e.target.value)} /></label>{type==='competition'&&<label>Klasse *<input required value={m.league} onChange={e => set('league',e.target.value)} /></label>}{(type==='competition'||type==='friendly')&&<label>Periode *<select required value={m.period} onChange={e => set('period',+e.target.value)}>{[1,2,3,4].map(x => <option key={x} value={x}>{x}e</option>)}</select></label>}<label>Locatie<select value={m.location} onChange={e => set('location',e.target.value)}><option value="home">Thuis</option><option value="away">Uit</option></select></label>{m.location==='home'&&<label>Spelbegeleider<input value={m.facilitator} onChange={e => set('facilitator',e.target.value)} /></label>}</div><small className="required-hint">* Verplicht voor deze wedstrijdsoort</small><label>Algemene wedstrijdnotitie<textarea value={m.notes} onChange={e => set('notes',e.target.value)} /></label><footer><button type="button" className="danger" onClick={remove}>Verwijderen</button><span /><button type="button" className="secondary" onClick={close}>Annuleren</button><button>Opslaan</button></footer></form></Modal> ;}
